function applyLogo(src) {
  const hdr = document.getElementById('headerBrandmark');
  const hdrFallback = document.getElementById('headerLogoFallback');
  const authBox = document.getElementById('authLogoBox');
  const authFallback = document.getElementById('authLogoFallback');

  if (!src || !src.trim()) return;

  function mount(container, fallback, cssText) {
    if (!container) { console.warn('applyLogo: element not found, skip'); return; }
    const img = document.createElement('img');
    img.alt = 'AMR Asia';
    img.style.cssText = cssText;
    img.onload = () => { if (fallback) fallback.style.display = 'none'; };
    img.onerror = () => { img.remove(); console.warn('applyLogo: image failed to decode/load'); };
    img.src = src;
    container.appendChild(img);
  }

  mount(hdr, hdrFallback, 'height:var(--logo-h);width:auto;max-width:160px;display:block;object-fit:contain');
  mount(authBox, authFallback, 'height:38px;width:auto;max-width:116px;display:block;object-fit:contain');
}
applyLogo(LOGO_SRC);

function confirmDlg(message, okLabel, onOk){
  let dlg = document.getElementById('confirmDlg');
  if(!dlg){
    dlg = document.createElement('div');
    dlg.id = 'confirmDlg';
    dlg.style.cssText = 'position:fixed;inset:0;z-index:500;background:rgba(20,26,34,.55);display:none;align-items:center;justify-content:center;padding:20px';
    dlg.innerHTML = `<div style="background:var(--surface);border-radius:16px;max-width:360px;width:100%;padding:24px;box-shadow:0 12px 40px rgba(20,26,34,.18)">
      <div id="confirmDlgMsg" style="font-size:15px;color:var(--ink);margin-bottom:20px;line-height:1.5"></div>
      <div style="display:flex;gap:10px;justify-content:flex-end">
        <button id="confirmDlgCancel" style="flex:1;padding:10px;border-radius:8px;background:var(--bg);color:var(--ink-soft);font-weight:600;font-size:14px;cursor:pointer;border:none">Cancel</button>
        <button id="confirmDlgOk" style="flex:1;padding:10px;border-radius:8px;background:var(--accent-fill);color:#fff;font-weight:600;font-size:14px;cursor:pointer;border:none">OK</button>
      </div>
    </div>`;
    document.body.appendChild(dlg);
    dlg.addEventListener('click', e=>{ if(e.target===dlg) dlg.style.display='none'; });
  }
  dlg.querySelector('#confirmDlgMsg').textContent = message || '';
  dlg.querySelector('#confirmDlgOk').textContent = okLabel || 'OK';
  const okBtn = dlg.querySelector('#confirmDlgOk');
  const cancelBtn = dlg.querySelector('#confirmDlgCancel');
  okBtn.onclick = ()=>{ dlg.style.display='none'; if(typeof onOk==='function') onOk(); };
  cancelBtn.onclick = ()=>{ dlg.style.display='none'; };
  dlg.style.display = 'flex';
}

