function openImageViewer(imgs){
  if(!imgs.length){toast('No photo',false);return;}
  let cur=0;
  const ov=document.createElement('div');
  ov.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.88);z-index:9999;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;padding:20px;box-sizing:border-box';
  ov.addEventListener('click',ev=>{if(ev.target===ov)ov.remove();});
  function render(){
    let scale=1,panX=0,panY=0,dragging=false,startX=0,startY=0,startPanX=0,startPanY=0,lastTap=0;
    ov.innerHTML='';
    const hd=document.createElement('div');hd.style.cssText='display:flex;align-items:center;justify-content:space-between;width:min(90vw,760px)';
    const lbl=document.createElement('span');lbl.style.cssText='color:#fff;font-size:14px;font-weight:600';lbl.textContent=imgs[cur].label+'  ('+(cur+1)+'/'+imgs.length+')';
    const xBtn=document.createElement('button');xBtn.textContent='✕';xBtn.style.cssText='background:rgba(255,255,255,.18);border:none;color:#fff;font-size:18px;width:36px;height:36px;border-radius:50%;cursor:pointer;display:flex;align-items:center;justify-content:center;flex-shrink:0';xBtn.onclick=()=>ov.remove();
    hd.appendChild(lbl);hd.appendChild(xBtn);ov.appendChild(hd);
    const wrap=document.createElement('div');wrap.style.cssText='width:min(90vw,760px);height:65vh;overflow:hidden;border-radius:10px;background:#111;touch-action:none';
    const img=document.createElement('img');img.src=imgs[cur].src;img.style.cssText='width:100%;height:100%;object-fit:contain;display:block;transition:transform .15s ease;transform-origin:center center;user-select:none;-webkit-user-drag:none;cursor:zoom-in';
    function apply(){img.style.transform=`translate(${panX}px,${panY}px) scale(${scale})`;img.style.cursor=scale>1?'grab':'zoom-in';}
    function toggleZoom(cx,cy){
      const rect=wrap.getBoundingClientRect();
      if(scale===1){
        scale=2.5;
        panX=-(cx-rect.left-rect.width/2)*(scale-1)/scale;
        panY=-(cy-rect.top-rect.height/2)*(scale-1)/scale;
      }else{scale=1;panX=0;panY=0;}
      apply();
    }
    img.addEventListener('dblclick',ev=>{ev.preventDefault();toggleZoom(ev.clientX,ev.clientY);});
    img.addEventListener('pointerdown',ev=>{
      const now=Date.now();
      if(now-lastTap<300){toggleZoom(ev.clientX,ev.clientY);lastTap=0;return;}
      lastTap=now;
      if(scale===1)return;
      dragging=true;startX=ev.clientX;startY=ev.clientY;startPanX=panX;startPanY=panY;
      img.style.transition='none';img.setPointerCapture(ev.pointerId);
    });
    img.addEventListener('pointermove',ev=>{if(!dragging)return;panX=startPanX+(ev.clientX-startX);panY=startPanY+(ev.clientY-startY);apply();});
    const endDrag=()=>{dragging=false;img.style.transition='transform .15s ease';};
    img.addEventListener('pointerup',endDrag);
    img.addEventListener('pointercancel',endDrag);
    apply();
    wrap.appendChild(img);ov.appendChild(wrap);
    if(imgs.length>1){
      const nav=document.createElement('div');nav.style.cssText='display:flex;align-items:center;gap:8px;flex-wrap:wrap;justify-content:center';
      const mkBtn=(txt,dis,fn)=>{const b=document.createElement('button');b.textContent=txt;b.style.cssText='padding:7px 16px;border-radius:8px;border:none;background:#fff;cursor:'+(dis?'default':'pointer')+';font-size:15px;opacity:'+(dis?.35:1);if(!dis)b.onclick=fn;return b;};
      nav.appendChild(mkBtn('◀',cur===0,()=>{cur--;render();}));
      imgs.forEach((im,i)=>{const tb=document.createElement('div');tb.style.cssText='width:46px;height:46px;border-radius:6px;overflow:hidden;cursor:pointer;border:2.5px solid '+(i===cur?'#D93A2B':'rgba(255,255,255,.3)');const ti=document.createElement('img');ti.src=im.src;ti.style.cssText='width:100%;height:100%;object-fit:cover';tb.appendChild(ti);tb.onclick=()=>{cur=i;render();};nav.appendChild(tb);});
      nav.appendChild(mkBtn('▶',cur===imgs.length-1,()=>{cur++;render();}));
      ov.appendChild(nav);
    }
    const hint=document.createElement('div');hint.style.cssText='color:rgba(255,255,255,.85);font-size:11px';hint.textContent='Double-click/double-tap to zoom, then drag to pan';
    ov.appendChild(hint);
  }
  render();document.body.appendChild(ov);
}
