  if(!assignStats.length){card.style.display='none';return;}
  card.style.display='';
  const role=AUTH.user?.role||'';
  const me=AUTH.user?.username||'';
  const fProj=$('#assignDashFProject');
  if(fProj){
    const prev=fProj.value;
    fProj.innerHTML='<option value="">All Projects</option>'+assignStats.map(p=>`<option value="${escAttr(p.project)}">${esc(p.project)}</option>`).join('');
    if(prev)fProj.value=prev;
  }
  const filterProj=fProj?fProj.value:'';
  let data=filterProj?assignStats.filter(p=>p.project===filterProj):assignStats;
  if(role==='inspector') data=data.map(p=>({...p,inspectors:p.inspectors.filter(i=>i.username===me)})).filter(p=>p.inspectors.length);
