$('#addMasterBtn').addEventListener('click',()=>editMaster(null));
$('#bulkDelMasterBtn')?.addEventListener('click',bulkDeleteMaster);
function editMaster(id){
  const m=id?master.find(x=>x.id===id):{project:'',system:'',typeLocation:'',locName:'',subName:'',equipment:'',brand:'',model:'',asset:'',serial:'',order:''};
  if(!m)return;
  let dlg=$('#masterDialog');
  if(!dlg){
    dlg=document.createElement('div'); dlg.id='masterDialog';
    dlg.style.cssText='position:fixed;inset:0;z-index:300;background:rgba(20,26,34,.55);display:flex;align-items:center;justify-content:center;padding:20px';
    document.body.appendChild(dlg);
  }
  const F=[
    ['project','Project',true],['system','System',false],['typeLocation','Location Type',false],
    ['locName','Location',false],['subName','Sub-location',false],
    ['asset','Equipment Type',false],['equipment','Equipment',true],['brand','Brand',false],
    ['model','Model',false],['serial','Serial Number',false],
    ['order','Order (used when generating Word/PDF — leave blank to sort alphabetically)',false]
  ];
  const fields=F.map(([k,label,req])=>`<div style="margin-bottom:10px">
      <label style="font-size:12px;font-weight:500;display:block;margin-bottom:4px">${label}${req?' <span style="color:#E2231A">*</span>':''}</label>
      <input class="tin mfield" data-k="${k}" value="${escAttr(m[k]||'')}" style="width:100%" placeholder="${label}" autocomplete="off">
    </div>`).join('');
  dlg.innerHTML=`<div style="background:var(--surface);border-radius:16px;max-width:520px;width:100%;padding:24px;box-shadow:var(--shadow-lift);max-height:90vh;overflow:auto">
    <h3 style="font-size:17px;font-weight:700;margin-bottom:4px">${id?'Edit Equipment':'Add Equipment'}</h3>
    <div style="font-size:12.5px;color:var(--ink-soft);margin-bottom:16px">Only edit the fields you need · type to pick from existing values within the same project</div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:0 14px">${fields}</div>
    <div style="display:flex;gap:8px;margin-top:14px">
      <button class="btn btn-soft" id="mCancel" style="flex:1">Cancel</button>
      <button class="btn btn-primary" id="mSave" style="flex:1">${id?'Save Changes':'Add'}</button>
    </div></div>`;

  const HIER=['project','system','typeLocation','locName','subName','equipment'];
  const fieldVal=(k)=>{const el=dlg.querySelector(`.mfield[data-k="${k}"]`);return el?el.value.trim():'';};
  const cascadeOptions=(level)=>{
    let rows=master;
    for(const lv of HIER){ if(lv===level)break; const v=fieldVal(lv); if(v) rows=rows.filter(r=>String(r[lv]||'')===v); }
    return uniq(rows.map(r=>r[level])).filter(Boolean);
  };
  const equipScopedOptions=(field)=>{
    let rows=master;
    const proj=fieldVal('project'), equip=fieldVal('equipment');
    if(proj) rows=rows.filter(r=>String(r.project||'')===proj);
    if(equip) rows=rows.filter(r=>String(r.equipment||'')===equip);
    return uniq(rows.map(r=>r[field])).filter(Boolean);
  };
  HIER.forEach(k=>{
    const el=dlg.querySelector(`.mfield[data-k="${k}"]`);
    if(el) upgradeToCombo(el,()=>k==='project'?uniq(master.map(r=>r.project)).filter(Boolean):cascadeOptions(k));
  });
  ['brand','model','asset','serial'].forEach(k=>{
    const el=dlg.querySelector(`.mfield[data-k="${k}"]`);
    if(el) upgradeToCombo(el,()=>equipScopedOptions(k));
  });
  dlg.style.display='flex';
  dlg.querySelector('#mCancel').onclick=()=>dlg.style.display='none';
  dlg.querySelector('#mSave').onclick=async()=>{
    const vals={};
    dlg.querySelectorAll('.mfield').forEach(inp=>{vals[inp.dataset.k]=inp.value.trim();});
    if(!vals.project||!vals.equipment){toast('Project and equipment are required',false);return;}
    const obj={id:id||uid(),...vals};
    const saveBtn=dlg.querySelector('#mSave');saveBtn.disabled=true;
    const r=await masterServer('masterUpsert',{rows:[masterToBackend(obj)]});
    saveBtn.disabled=false;
    if(!r)return;
    if(id)master=master.map(x=>x.id===id?obj:x);else master.push(obj);
    dlg.style.display='none';
    persistMaster();toast(id?'Updated':'Equipment added',true);
  };
}
function delMaster(id){confirmDlg('Delete this equipment?','Delete',async()=>{const r=await masterServer('masterDelete',{ids:[id]});if(!r)return;master=master.filter(x=>x.id!==id);persistMaster();toast('Deleted',true);});}
function bulkDeleteMaster(){
  const q=$('#masterSearch')?$('#masterSearch').value.trim().toLowerCase():'';
  const fp=$('#masterFProject')?$('#masterFProject').value:'';
  const fs=$('#masterFSystem')?$('#masterFSystem').value:'';
  const fl=$('#masterFLoc')?$('#masterFLoc').value:'';
  const fsub=$('#masterFSub')?$('#masterFSub').value:'';
  const feq=$('#masterFEquip')?$('#masterFEquip').value:'';
  if(!q&&!fp&&!fs&&!fl&&!fsub&&!feq){toast('Please set at least one filter condition before deleting',false);return;}
  let list=master.filter(m=>!q||[m.project,m.system,m.typeLocation,m.locName,m.subName,m.equipment,m.brand,m.model,m.asset,m.serial].join(' ').toLowerCase().includes(q));
  if(fp)list=list.filter(m=>m.project===fp);
  if(fs)list=list.filter(m=>m.system===fs);
  if(fl)list=list.filter(m=>m.locName===fl);
  if(fsub)list=list.filter(m=>m.subName===fsub);
  if(feq)list=list.filter(m=>m.equipment===feq);
  if(!list.length){toast('No records match the condition',false);return;}

  const parts=[];
  if(fp)parts.push('Project: '+fp);
  if(fs)parts.push('System: '+fs);
  if(fl)parts.push('Location: '+fl);
  if(fsub)parts.push('Sub-location: '+fsub);
  if(feq)parts.push('Equipment: '+feq);
  if(q)parts.push('Search: "'+q+'"');
  const criteriaHtml=parts.map(p=>'<div style="color:var(--danger-text);font-weight:600;font-size:14px">'+esc(p)+'</div>').join('');
  showConfirmDialog(
    'Confirm Deletion',
    criteriaHtml+
    '<div style="margin-top:10px;font-size:14px;color:var(--ink-soft)">This will permanently delete <b>'+list.length+' records</b><br><span style="color:var(--ink-faint);font-size:13px">This cannot be undone</span></div>',
    async()=>{
      const idList=list.map(m=>m.id);
      const r=await masterServer('masterDelete',{ids:idList});
      if(!r)return;
      const ids=new Set(idList);
      master=master.filter(m=>!ids.has(m.id));
      persistMaster();
      toast('Deleted '+r.deleted+' records',true);
    }
  );
}
function showConfirmDialog(title,bodyHtml,onOk){
  const ov=document.createElement('div');
  ov.style.cssText='position:fixed;inset:0;z-index:9000;background:rgba(20,26,34,.45);display:flex;align-items:center;justify-content:center;padding:20px';
  ov.innerHTML=`<div style="background:var(--surface);border-radius:16px;box-shadow:0 8px 40px rgba(0,0,0,.18);width:100%;max-width:400px;padding:28px 28px 22px">
    <div style="font-size:17px;font-weight:700;color:var(--ink);margin-bottom:14px">${esc(title)}</div>
    <div style="margin-bottom:20px;line-height:1.6">${bodyHtml}</div>
    <div style="display:flex;gap:10px;justify-content:flex-end">
      <button id="_cdCancel" style="padding:9px 22px;border-radius:9px;border:1px solid var(--line);background:var(--surface);color:var(--ink);font-size:14px;cursor:pointer;font-weight:500">Cancel</button>
      <button id="_cdOk" style="padding:9px 22px;border-radius:9px;border:none;background:#DC2626;color:#fff;font-size:14px;cursor:pointer;font-weight:600">Delete</button>
    </div>
  </div>`;
  document.body.appendChild(ov);
  ov.querySelector('#_cdCancel').onclick=()=>ov.remove();
  ov.querySelector('#_cdOk').onclick=()=>{ov.remove();onOk();};
  ov.addEventListener('click',e=>{if(e.target===ov)ov.remove();});
}

const masterToBackend=m=>({id:m.id,project:m.project,system:m.system,typeLocation:m.typeLocation,location:m.locName,sublocation:m.subName,equipment:m.equipment,brand:m.brand,model:m.model,asset:m.asset,serial:m.serial,order:m.order||''});
const masterNs=s=>String(s||'').replace(/[\r\n]+/g,' ').replace(/\s+/g,' ').trim();
const masterFromBackend=m=>({id:m.id,project:masterNs(m.project),system:masterNs(m.system),typeLocation:masterNs(m.typeLocation),locName:masterNs(m.location),subName:masterNs(m.sublocation),equipment:masterNs(m.equipment),brand:masterNs(m.brand),model:masterNs(m.model),asset:masterNs(m.asset),serial:masterNs(m.serial),order:m.order||''});
async function persistMaster(){await sSet(MASTER_KEY,JSON.stringify(master));refreshDerived();renderMaster();if(combos.project)setDisabledStates();}
async function loadMasterFromBackend(){if(!AUTH.token)return;const r=await api(ACT.listMaster,{});if(r&&r.ok&&Array.isArray(r.master)){master=r.master.map(masterFromBackend);await persistMaster();}}
async function masterServer(action,payload){const r=await api(ACT[action],payload);if(!(r&&r.ok)){toast((r&&r.message)||'Could not save to the server, please try again',false);return null;}return r;}

function updateStats(){$('#statCount').textContent=entries.length;$('#savedPill').textContent=entries.length;}

$('#exportXlsx').addEventListener('click',async()=>{if(!entries.length){toast('No data to export yet',false);return;}try{await loadLib('xlsx');}catch(e){toast('Could not load the Excel library. Check your connection and try again',false); return;}const rows=entries.map(e=>({'Date recorded':fmtDate(e.createdAt,true),'Project':e.project,'System':e.system,'Location':e.locName,'Sub-location':e.subName,'Equipment':e.equipment,'Brand':e.brand,'Model':e.model,'Equipment Type':e.asset,'Serial Number':e.serial,'Inspector Name':e.inspector,'Note':e.note}));const ws=XLSX.utils.json_to_sheet(rows);const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Records');XLSX.writeFile(wb,`records_${fileStamp(Date.now())}.xlsx`);toast(`Exported to Excel (${entries.length} records)`,true);});
const MASTER_IMPORT_COLS=[['order','Order'],['project','Project'],['system','System'],['typeLocation','Location Type'],['locName','Location'],['subName','Sub-location'],['asset','Equipment Type'],['equipment','Equipment'],['brand','Brand'],['model','Model'],['serial','Serial Number']];

function masterOrderKey(o){return [o.project,o.typeLocation,o.locName,o.subName,o.equipment].map(x=>String(x||'').trim()).join('|');}
function buildMasterOrderMap(){
  const map={};
  master.forEach(m=>{ const n=Number(m.order); if(m.order!==undefined&&m.order!==''&&!isNaN(n)) map[masterOrderKey(m)]=n; });
  return map;
}
function masterOrderOf(orderMap,e){ const v=orderMap[masterOrderKey(e)]; return v===undefined?Infinity:v; }
async function downloadMasterTemplate(){try{await loadLib('xlsx');const ws=XLSX.utils.aoa_to_sheet([MASTER_IMPORT_COLS.map(c=>c[1])]);const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Master');XLSX.writeFile(wb,'master_template.xlsx');}catch(e){toast('Failed to load form',false);}}
async function downloadMasterData(){try{if(!master.length){toast('No Master Data yet',false);return;}await loadLib('xlsx');const rows=master.map(m=>MASTER_IMPORT_COLS.map(c=>m[c[0]]||''));const ws=XLSX.utils.aoa_to_sheet([MASTER_IMPORT_COLS.map(c=>c[1]),...rows]);const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Master');XLSX.writeFile(wb,'master_data.xlsx');toast('Master Data downloaded',true);}catch(e){toast('Failed to load data',false);}}

if($('#fileXlsx'))$('#fileXlsx').addEventListener('change',async(ev)=>{
  const file=ev.target.files[0]; if(!file)return;
  const prev=$('#importPreview');
  try{
    await loadLib('xlsx');
    const buf=await file.arrayBuffer();
    const wb=XLSX.read(buf,{type:'array'});
    const ws=wb.Sheets[wb.SheetNames[0]];
    const rowsAoa=XLSX.utils.sheet_to_json(ws,{header:1});
    const header=rowsAoa[0]||[];
    const colIdx={};MASTER_IMPORT_COLS.forEach(([key,label])=>{const idx=header.findIndex(h=>String(h).replace(/^﻿/,'').trim()===label);if(idx>=0)colIdx[key]=idx;});
    const normStr=s=>String(s||'').replace(/[\r\n]+/g,' ').replace(/\s+/g,' ').trim();
    const mapped=rowsAoa.slice(1).map((r,i)=>({r,rowNo:i+2})).filter(x=>x.r&&x.r.length).map(({r,rowNo})=>{
      const obj={_row:rowNo};Object.keys(colIdx).forEach(key=>{obj[key]=normStr(r[colIdx[key]]);});
      return obj;
    }).filter(o=>Object.keys(o).some(k=>k!=='_row'&&o[k]));
    const rows=mapped.filter(o=>o.project&&o.equipment);
    const clientInvalid=mapped.filter(o=>!(o.project&&o.equipment)).map(o=>({row:o._row,reason:'missing',firstRow:'',project:o.project||'',location:o.locName||'',sublocation:o.subName||'',equipment:o.equipment||'',brand:o.brand||'',model:o.model||'',serial:o.serial||''}));
    if(!rows.length){if(prev)prev.innerHTML=`<div class="empty">No importable data found (must have at least the "Project" and "Equipment" columns)</div>`;return;}
    const payload=rows.map(r=>({id:uid(),project:r.project||'',system:r.system||'',typeLocation:r.typeLocation||'',location:r.locName||'',sublocation:r.subName||'',equipment:r.equipment||'',brand:r.brand||'',model:r.model||'',asset:r.asset||'',serial:r.serial||'',order:r.order||'',_row:r._row}));
    const res=await masterServer('masterImport',{rows:payload});
    if(res){
      await loadMasterFromBackend();
      const msg=`Imported ${res.added} new records`+(res.skipped?` · skipped ${res.skipped} duplicates`:'');
      renderImportReport(prev,res,clientInvalid,msg);
      toast(msg,true);
    }else if(prev)prev.innerHTML=`<div class="empty">Import failed</div>`;
  }catch(e){
    if(prev)prev.innerHTML=`<div class="empty">Failed to read file</div>`;
    toast('Failed to read file',false);
  }
  ev.target.value='';
});

async function fetchImageBuffer(url){
  if(!url) return null;
  try{
    const m=String(url).match(/[-\w]{25,}/);
    if(m) url=DRIVE_THUMB+m[0]+'&sz=w800';
    const r=await api('fetchImageAsBase64',{url});
    if(!r||!r.ok||!r.base64) return null;
    const bin=atob(r.base64); const len=bin.length; const buf=new Uint8Array(len);
    for(let i=0;i<len;i++) buf[i]=bin.charCodeAt(i);
    return buf.buffer;
  }catch(e){ return null; }
}

async function fetchImageDataUrl(url){
  if(!url) return '';
  if(String(url).startsWith('data:')) return url;
  try{
    const m=String(url).match(/[-\w]{25,}/);
    let u=url; if(m) u=DRIVE_THUMB+m[0]+'&sz=w800';
    const r=await api('fetchImageAsBase64',{url:u});
    if(!r||!r.ok||!r.base64) return '';
    return `data:${r.mimeType||'image/jpeg'};base64,${r.base64}`;
  }catch(e){ return ''; }
}

function makeContinentBlob(centerLon,centerLat,baseSize,points,seed){
  const verts=[];
  for(let i=0;i<points;i++){
    const a=(i/points)*Math.PI*2;
    const r=baseSize*(0.7+0.3*Math.sin(a*3+seed)+0.15*Math.cos(a*5+seed*1.7));
    verts.push({lon:centerLon+Math.cos(a)*r,lat:Math.max(-85,Math.min(85,centerLat+Math.sin(a)*r*0.6))});
  }
  return verts;
}
const EARTH_CONTINENTS=[
  {color:'#c9a876',verts:makeContinentBlob(15,10,42,10,1.1)},
  {color:'#4a9a56',verts:makeContinentBlob(65,50,46,10,2.3)},
  {color:'#3f8a4c',verts:makeContinentBlob(-100,42,38,9,3.6)},
  {color:'#4a9a56',verts:makeContinentBlob(-60,-15,26,8,4.4)},
  {color:'#3f8a4c',verts:makeContinentBlob(135,-25,22,8,5.8)}
];
const EARTH_CLOUDS=[
  {lon:-30,lat:20,size:22},{lon:40,lat:-10,size:18},{lon:100,lat:30,size:16},
  {lon:-120,lat:-20,size:20},{lon:160,lat:5,size:14},{lon:-10,lat:-40,size:18}
];

const EARTH_CITY_LIGHTS=[
  {lon:10,lat:50},{lon:20,lat:48},{lon:30,lat:55},{lon:35,lat:31},{lon:55,lat:25},
  {lon:77,lat:20},{lon:88,lat:23},{lon:105,lat:30},{lon:120,lat:35},{lon:139,lat:36},
  {lon:-74,lat:41},{lon:-87,lat:42},{lon:-46,lat:-23},{lon:151,lat:-34},{lon:31,lat:30}
];
const EARTH_SUN_DIR={x:-0.55,y:-0.55,z:0.62};
function projectGlobe(lonDeg,latDeg,rotDeg,R,cx,cy){
  const lon=(lonDeg+rotDeg)*Math.PI/180, lat=Math.max(-85,Math.min(85,latDeg))*Math.PI/180;
  const nx=Math.cos(lat)*Math.sin(lon), ny=-Math.sin(lat), nz=Math.cos(lat)*Math.cos(lon);
  return {x:cx+R*nx,y:cy+R*ny,z:nz,nx,ny,nz};
}
function drawEarth(canvas,rot){
  const ctx=canvas.getContext('2d'); if(!ctx) return;
  const W=canvas.width,H=canvas.height,cx=W/2,cy=H/2,R=W*0.47;
  ctx.clearRect(0,0,W,H);
  ctx.save();
  ctx.beginPath();ctx.arc(cx,cy,R,0,Math.PI*2);ctx.closePath();ctx.clip();
  const ocean=ctx.createRadialGradient(cx-R*0.35,cy-R*0.4,R*0.15,cx,cy,R*1.05);
  ocean.addColorStop(0,'#a9e8fb');ocean.addColorStop(.35,'#2f8fd6');ocean.addColorStop(.7,'#175a9e');ocean.addColorStop(1,'#082346');
  ctx.fillStyle=ocean;ctx.fillRect(0,0,W,H);
  EARTH_CONTINENTS.forEach(c=>{
    const pts=c.verts.map(v=>projectGlobe(v.lon,v.lat,rot,R,cx,cy));
    const avgZ=pts.reduce((s,p)=>s+p.z,0)/pts.length;
    if(avgZ<=0.02) return;
    ctx.beginPath();
    pts.forEach((p,i)=>i===0?ctx.moveTo(p.x,p.y):ctx.lineTo(p.x,p.y));
    ctx.closePath();
    ctx.globalAlpha=Math.min(1,avgZ+0.25);
    ctx.fillStyle=c.color;
    ctx.fill();
    ctx.globalAlpha=1;
  });
  ctx.fillStyle='#ffffff';
  EARTH_CLOUDS.forEach(cl=>{
    const p=projectGlobe(cl.lon,cl.lat,rot*0.6,R,cx,cy);
    if(p.z<=0) return;
    const rad=cl.size*R/100*Math.max(.3,p.z);
    ctx.globalAlpha=.35*Math.max(.3,p.z);
    ctx.beginPath();ctx.ellipse(p.x,p.y,rad,rad*0.5,0,0,Math.PI*2);ctx.fill();
  });
  ctx.globalAlpha=1;

  const night=ctx.createLinearGradient(cx-R*0.6,cy-R*0.6,cx+R*0.75,cy+R*0.75);
  night.addColorStop(0,'rgba(0,0,10,0)');night.addColorStop(.55,'rgba(0,0,10,0)');night.addColorStop(1,'rgba(0,0,12,.6)');
  ctx.fillStyle=night;
  ctx.beginPath();ctx.arc(cx,cy,R,0,Math.PI*2);ctx.fill();

  EARTH_CITY_LIGHTS.forEach(cl=>{
    const p=projectGlobe(cl.lon,cl.lat,rot,R,cx,cy);
    if(p.z<=0.04) return;
    const lit=p.nx*EARTH_SUN_DIR.x+p.ny*EARTH_SUN_DIR.y+p.nz*EARTH_SUN_DIR.z;
    if(lit>0.08) return;
    ctx.globalAlpha=0.85;
    ctx.fillStyle='#ffdf94';
    ctx.beginPath();ctx.arc(p.x,p.y,Math.max(1,R*0.014),0,Math.PI*2);ctx.fill();
  });
  ctx.globalAlpha=1;
  ctx.restore();
  const rim=ctx.createRadialGradient(cx,cy,R*0.86,cx,cy,R*1.02);
  rim.addColorStop(0,'rgba(140,200,255,0)');rim.addColorStop(1,'rgba(140,200,255,.55)');
  ctx.beginPath();ctx.arc(cx,cy,R*1.02,0,Math.PI*2);ctx.fillStyle=rim;ctx.fill();
  const spec=ctx.createRadialGradient(cx-R*0.4,cy-R*0.45,0,cx-R*0.4,cy-R*0.45,R*0.5);
  spec.addColorStop(0,'rgba(255,255,255,.35)');spec.addColorStop(1,'rgba(255,255,255,0)');
  ctx.beginPath();ctx.arc(cx,cy,R,0,Math.PI*2);ctx.fillStyle=spec;ctx.fill();

  const flare=ctx.createRadialGradient(cx-R*1.25,cy-R*1.25,0,cx-R*1.25,cy-R*1.25,R*1.3);
  flare.addColorStop(0,'rgba(255,250,235,.55)');flare.addColorStop(.3,'rgba(255,240,200,.18)');flare.addColorStop(1,'rgba(255,240,200,0)');
  ctx.fillStyle=flare;
  ctx.beginPath();ctx.arc(cx-R*1.25,cy-R*1.25,R*1.3,0,Math.PI*2);ctx.fill();
}

let _warpRAF=null,_earthRAF=null,_earthRot=0;
function startWarpAnimation(){
  const ov=$('#warpOverlay'); if(!ov) return;
  ov.style.display='block';
  const done=$('#warpDone'); if(done) done.style.display='none';
  if(_earthRAF){cancelAnimationFrame(_earthRAF);_earthRAF=null;}
  const canvas=$('#warpCanvas'); if(!canvas) return;
  const ctx=canvas.getContext('2d');
  const resize=()=>{canvas.width=innerWidth;canvas.height=innerHeight;};
  resize();

  const stars=Array.from({length:280},()=>({angle:Math.random()*Math.PI*2,radius:Math.random()*80,speed:2+Math.random()*4}));
  function frame(){
    ctx.fillStyle='rgba(4,6,16,.28)';
    ctx.fillRect(0,0,canvas.width,canvas.height);
    const cx=canvas.width/2, cy=canvas.height*0.42, maxR=Math.hypot(canvas.width,canvas.height)*0.65;
    stars.forEach(s=>{
      const x1=cx+Math.cos(s.angle)*s.radius, y1=cy+Math.sin(s.angle)*s.radius;
      s.radius+=s.speed;
      const x2=cx+Math.cos(s.angle)*s.radius, y2=cy+Math.sin(s.angle)*s.radius;
      const alpha=Math.min(1,s.radius/maxR+.15);
      ctx.strokeStyle=`rgba(180,220,255,${alpha})`;
      ctx.lineWidth=Math.min(2.4,s.radius/220);
      ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();
      if(s.radius>maxR){s.radius=0;s.angle=Math.random()*Math.PI*2;}
    });
    _warpRAF=requestAnimationFrame(frame);
  }
  window.addEventListener('resize',resize);
  frame();
}
function setWarpStatus(msg){
  const el=$('#warpStatus'); if(el) el.innerHTML=msg;
}
function finishWarpAnimation(){
  if(_warpRAF){cancelAnimationFrame(_warpRAF);_warpRAF=null;}
  const done=$('#warpDone'); if(done) done.style.display='flex';
  setWarpStatus('');
  const canvas=$('#warpPlanet');
  if(canvas){
    (function spin(){
      _earthRot+=0.25;
      drawEarth(canvas,_earthRot);
      _earthRAF=requestAnimationFrame(spin);
    })();
  }
}
function closeWarpAnimation(){
  const ov=$('#warpOverlay'); if(ov) ov.style.display='none';
  const done=$('#warpDone'); if(done) done.style.display='none';
  if(_warpRAF){cancelAnimationFrame(_warpRAF);_warpRAF=null;}
  if(_earthRAF){cancelAnimationFrame(_earthRAF);_earthRAF=null;}
}

async function generateWordTemplate(){
  try{await loadLib('docx');}catch(e){toast('Could not load the Word library. Check your connection and try again',false);return;}

  let entries=getSavedFilteredList();
  if(!entries.length){toast('No data matches the current filter',false);return;}
  const orderMap=buildMasterOrderMap();
  const {Document,Packer,Paragraph,TextRun,HeadingLevel,Table,TableRow,TableCell,ImageRun,AlignmentType,BorderStyle,WidthType,TableOfContents,Header,Footer,PageNumber,TabStopType,TabStopPosition,TableLayoutType,VerticalAlign}=docx;
  const groupBy='location';
  const fieldKey={project:'project',system:'system',location:'locName'}[groupBy];
  const groupLabel={project:'Project',system:'System',location:'Location'}[groupBy];

  const projectNames=uniq(entries.map(e=>e.project).filter(Boolean));
  const projectName=projectNames.length?projectNames.join(', '):'-';
  const btn=$('#openWordReportBtn');if(btn)btn.disabled=true;
  startWarpAnimation();
  setWarpStatus('Preparing data...');
  try{

  const PAGE_SIZE={width:11906,height:16838};
  const PAGE_MARGIN={top:1400,bottom:1100,left:1130,right:1130};
  const CONTENT_DXA=PAGE_SIZE.width-PAGE_MARGIN.left-PAGE_MARGIN.right-60;
  const FONT='TH Sarabun New',BLACK='000000',DARK='1A232E',GREY='5B6573';
  const T=(t,o={})=>new TextRun({text:t,font:FONT,size:(o.size||28),bold:o.bold||false,color:o.color||'000000'});
  const P=(runs,o={})=>new Paragraph({children:Array.isArray(runs)?runs:[runs],alignment:o.align,spacing:o.spacing,heading:o.heading,keepNext:o.keepNext,keepLines:o.keepLines});
  const noBorders=()=>{const n={style:BorderStyle.NONE,size:0,color:'FFFFFF'};return{top:n,bottom:n,left:n,right:n,insideHorizontal:n,insideVertical:n};};

  let logoBuf=null;
  if(LOGO_SRC&&LOGO_SRC.trim()){
    try{
      if(LOGO_SRC.startsWith('data:')){

        const b64=LOGO_SRC.split(',')[1];
        if(b64){const bin=atob(b64);const len=bin.length;const buf=new Uint8Array(len);for(let i=0;i<len;i++)buf[i]=bin.charCodeAt(i);logoBuf=buf.buffer;}
      } else {

        setWarpStatus('Loading logo...');
        logoBuf = await fetchImageBuffer(LOGO_SRC);
      }
    }catch(e){logoBuf=null;}
  }

  const tocKids=[P(T('Table of Contents',{size:44,bold:true,color:DARK}),{align:AlignmentType.CENTER}),new TableOfContents('Table of Contents',{hyperlink:true,headingStyleRange:'1-3'})];

  setWarpStatus('Grouping data...');
  const bodyKids=[];

  async function pushEquipmentBlock(e, idx){

    bodyKids.push(P(T(`${idx}. ${e.equipment||'(Equipment not specified)'}`,{size:28,bold:true,color:DARK}),{heading:HeadingLevel.HEADING_3,keepNext:true}));
    const bm=[e.brand?'Brand '+e.brand:'',e.model?'Model '+e.model:''].filter(Boolean).join('  ');if(bm)bodyKids.push(P(T(bm,{size:28}),{keepNext:true}));
    const meta=[e.serial?'Serial: '+e.serial:'',e.asset?'Type: '+e.asset:''].filter(Boolean).join('   ');if(meta)bodyKids.push(P(T(meta,{size:24,color:GREY}),{keepNext:true}));
    const loc=[e.locName,e.subName].filter(Boolean).join(' ');if(loc)bodyKids.push(P(T(loc,{size:26,color:GREY}),{keepNext:true}));
    const photoSlots=[
      {u:e.thumbMain||e.imgMain,cap:'Full equipment photo'},
      {u:e.thumbSticker||e.imgSticker,cap:'Sticker photo'},
      {u:e.thumb3||e.img3,cap:'Additional photo 1'},
      {u:e.thumb4||e.img4,cap:'Additional photo 2'}
    ].filter(s=>s.u);
    if(photoSlots.length){
      setWarpStatus('Loading images...');
      const bufs=await Promise.all(photoSlots.map(s=>fetchImageBuffer(s.u)));
      const slotBufs=photoSlots.map((s,i)=>({buf:bufs[i],cap:s.cap})).filter(s=>s.buf);
      const CELL_DXA_HALF=CONTENT_DXA/2, CELL_DXA_FULL=CONTENT_DXA;
      const cellFor=(slot,wide)=>new TableCell({borders:noBorders(),columnSpan:wide?2:1,width:{size:wide?CELL_DXA_FULL:CELL_DXA_HALF,type:WidthType.DXA},children:[
        new Paragraph({alignment:AlignmentType.CENTER,children:[new ImageRun({data:slot.buf,transformation:{width:wide?420:300,height:wide?315:225}})]}),
      ]});

      const spacerRow=()=>new TableRow({cantSplit:true,children:[new TableCell({borders:noBorders(),columnSpan:2,width:{size:CELL_DXA_FULL,type:WidthType.DXA},children:[new Paragraph({})]})]});
      const rows=[];
      for(let ri=0;ri<slotBufs.length;ri+=2){
        const left=slotBufs[ri],right=slotBufs[ri+1];
        if(rows.length) rows.push(spacerRow());
        rows.push(new TableRow({cantSplit:true,children: right?[cellFor(left),cellFor(right)]:[cellFor(left,true)]}));
      }
      if(rows.length)bodyKids.push(new Table({width:{size:CELL_DXA_FULL,type:WidthType.DXA},columnWidths:[CELL_DXA_HALF,CELL_DXA_HALF],layout:TableLayoutType.FIXED,rows}));
    }
    if(e.note)bodyKids.push(P(T(`Note: ${e.note}`,{size:24,color:GREY})));
    bodyKids.push(new Paragraph({}));
  }

  const useTypeLoc = groupBy==='location' && entries.some(e=>e.typeLocation);

  const byOrderThenAlpha=(getItemsA,getItemsB,a,b)=>{
    const oa=Math.min(...getItemsA.map(e=>masterOrderOf(orderMap,e)));
    const ob=Math.min(...getItemsB.map(e=>masterOrderOf(orderMap,e)));
    if(oa!==ob) return oa-ob;
    return a.localeCompare(b,'th');
  };
  const sortItemsByOrder=(items)=>items.slice().sort((a,b)=>{
    const oa=masterOrderOf(orderMap,a),ob=masterOrderOf(orderMap,b);
    if(oa===Infinity&&ob===Infinity) return 0;
    return oa-ob;
  });
  if(useTypeLoc){
    const typeGroups={};entries.forEach(e=>{const tk=e.typeLocation||'(Location type not specified)';(typeGroups[tk]=typeGroups[tk]||[]).push(e);});
    const typeNames=Object.keys(typeGroups).sort((a,b)=>byOrderThenAlpha(typeGroups[a],typeGroups[b],a,b));
    for(let ti=0;ti<typeNames.length;ti++){
      const tname=typeNames[ti];const titems=typeGroups[tname];
      bodyKids.push(P(T(`${ti+1}. ${tname}`,{size:32,bold:true,color:BLACK}),{heading:HeadingLevel.HEADING_1}));
      const locGroups={};titems.forEach(e=>{const lk=e.locName||'(Location not specified)';(locGroups[lk]=locGroups[lk]||[]).push(e);});
      const locNames=Object.keys(locGroups).sort((a,b)=>byOrderThenAlpha(locGroups[a],locGroups[b],a,b));
      for(let li=0;li<locNames.length;li++){
        const lname=locNames[li];const litems=sortItemsByOrder(locGroups[lname]);
        bodyKids.push(P(T(lname,{size:30,bold:true,color:DARK}),{heading:HeadingLevel.HEADING_2,align:AlignmentType.CENTER}));
        bodyKids.push(new Paragraph({}));
        for(let i=0;i<litems.length;i++) await pushEquipmentBlock(litems[i], i+1);
      }
    }
  } else {
    bodyKids.unshift(P(T(groupLabel,{size:36,bold:true,color:BLACK}),{heading:HeadingLevel.HEADING_1}));
    const groups={};entries.forEach(e=>{const k=e[fieldKey]||'(unspecified)';(groups[k]=groups[k]||[]).push(e);});
    const groupNames=Object.keys(groups).sort((a,b)=>byOrderThenAlpha(groups[a],groups[b],a,b));
    for(let gi=0;gi<groupNames.length;gi++){
      const gname=groupNames[gi];const items=sortItemsByOrder(groups[gname]);
      bodyKids.push(P(T(gname,{size:30,bold:true,color:DARK}),{heading:HeadingLevel.HEADING_2}));
      bodyKids.push(new Paragraph({}));
      for(let i=0;i<items.length;i++) await pushEquipmentBlock(items[i], i+1);
    }
  }

  setWarpStatus('Building header/footer...');
  const HDR_DXA_LOGO=Math.round(CONTENT_DXA*0.23), HDR_DXA_TEXT=CONTENT_DXA-Math.round(CONTENT_DXA*0.23);
  const hdrLeft=new TableCell({borders:noBorders(),width:{size:HDR_DXA_LOGO,type:WidthType.DXA},children:[
    logoBuf?new Paragraph({children:[new ImageRun({data:logoBuf,transformation:{width:90,height:56}})]}):P(T('AMR ASIA',{bold:true,color:'E2231A'}))
  ]});
  const hdrRight=new TableCell({borders:noBorders(),width:{size:HDR_DXA_TEXT,type:WidthType.DXA},children:[
    P(T(projectName,{size:24,bold:true}),{align:AlignmentType.RIGHT})
  ]});

  const header=new Header({children:[new Table({width:{size:CONTENT_DXA,type:WidthType.DXA},columnWidths:[HDR_DXA_LOGO,HDR_DXA_TEXT],layout:TableLayoutType.FIXED,borders:noBorders(),rows:[new TableRow({children:[hdrLeft,hdrRight]})]}),new Paragraph({})]});
  const footer=new Footer({children:[new Table({width:{size:CONTENT_DXA,type:WidthType.DXA},columnWidths:[Math.round(CONTENT_DXA*0.7),Math.round(CONTENT_DXA*0.3)],layout:TableLayoutType.FIXED,borders:noBorders(),rows:[new TableRow({children:[
    new TableCell({borders:noBorders(),width:{size:Math.round(CONTENT_DXA*0.7),type:WidthType.DXA},children:[new Paragraph({children:[T(`Project: ${projectName}`,{size:22})]})]}),
    new TableCell({borders:noBorders(),width:{size:Math.round(CONTENT_DXA*0.3),type:WidthType.DXA},children:[new Paragraph({alignment:AlignmentType.RIGHT,children:[
      new TextRun({text:'Page ',font:FONT,size:22}),
      new TextRun({children:[PageNumber.CURRENT],font:FONT,size:22}),
      new TextRun({text:' of ',font:FONT,size:22}),
      new TextRun({children:[PageNumber.TOTAL_PAGES],font:FONT,size:22})
    ]})]})
  ]})]})]})

  setWarpStatus('Compressing file...');

  const doc=new Document({styles:{
    default:{document:{run:{font:FONT}}},
    paragraphStyles:[
      {id:'TOC1',name:'toc 1',basedOn:'Normal',next:'Normal',run:{font:FONT,size:28}},
      {id:'TOC2',name:'toc 2',basedOn:'Normal',next:'Normal',run:{font:FONT,size:28}},
      {id:'TOC3',name:'toc 3',basedOn:'Normal',next:'Normal',run:{font:FONT,size:28}}
    ]
  },sections:[
    {properties:{page:{size:PAGE_SIZE,margin:PAGE_MARGIN}},headers:{default:header},footers:{default:footer},children:tocKids},
    {properties:{page:{size:PAGE_SIZE,margin:PAGE_MARGIN}},headers:{default:header},footers:{default:footer},children:bodyKids}
  ]});
  const blob=await Packer.toBlob(doc);
  const fn=`Equipment Report_${projectName}_${fileStamp(Date.now())}.docx`;
  finishWarpAnimation();
  setTimeout(()=>{
    const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=fn;a.click();URL.revokeObjectURL(a.href);
    if(btn)btn.disabled=false;
    toast('Word document generated',true);
    setTimeout(closeWarpAnimation,1500);
  },1400);
  }catch(err){
    closeWarpAnimation();
    if(btn)btn.disabled=false;
    toast('Failed to generate report: '+((err&&err.message)||'unknown error'),false);
    console.error('generateWordTemplate error:',err);
  }
}
