if($('#fileUsers'))$('#fileUsers').addEventListener('change',async(ev)=>{
  const file=ev.target.files[0]; if(!file)return;
  const msg=$('#usersImportMsg');
  try{
    await loadLib('xlsx');
    const buf=await file.arrayBuffer();
    const wb=XLSX.read(buf,{type:'array'});
    const ws=wb.Sheets[wb.SheetNames[0]];
    const rowsAoa=XLSX.utils.sheet_to_json(ws,{header:1});
    const header=rowsAoa[0]||[];
    const cols=['username','password','name','role','project','email'];
    const colIdx={};cols.forEach(key=>{const idx=header.findIndex(h=>String(h).replace(/^﻿/,'').trim()===key);if(idx>=0)colIdx[key]=idx;});
    const rows=rowsAoa.slice(1).filter(r=>r&&r.length).map(r=>{
      const obj={};cols.forEach(key=>{if(colIdx[key]!==undefined)obj[key]=String(r[colIdx[key]]||'').trim();});
      return obj;
    }).filter(o=>o.username&&o.password);
    if(!rows.length){if(msg)msg.innerHTML=`<div class="empty">No importable data found (must have username and password columns)</div>`;return;}
    const r=await api('bulkCreateUsers',{rows});
    if(r&&r.ok){
      if(msg)msg.innerHTML=`<div class="empty" style="color:var(--ok)">Added ${r.created} users${r.skipped?` (skipped ${r.skipped} duplicate usernames)`:''}</div>`;
      toast(`Added ${r.created} users`,true);
      await loadUsers();
    }else{
      if(msg)msg.innerHTML=`<div class="empty">Import failed</div>`;
      toast((r&&r.message)||'Import failed',false);
    }
  }catch(e){
    if(msg)msg.innerHTML=`<div class="empty">Failed to read file</div>`;
    toast('Failed to read file',false);
  }
  ev.target.value='';
});

