function _buildAssignCards(list){
  return list.map(a=>{
    const scopeLabel=a.scopeType==='project'?a.project
      :a.scopeType==='loc'?a.locName
      :a.scopeType==='sub'?(a.locName+' › '+a.subName)
      :a.scopeType==='equip'?(a.subName+' › '+a.equipment)
      :('Fill missing data: '+(a.equipment||''));
    return `<div class="assign-card">
      <div style="flex:1;min-width:0">
        <div style="font-size:13px;font-weight:600;color:var(--ink);margin-bottom:2px">${esc(scopeLabel)}</div>
        <div style="font-size:12px;color:var(--ink-soft)">Project: ${esc(a.project)}${a.note?' · '+esc(a.note):''}</div>
        <div style="font-size:11px;color:var(--ink-faint);margin-top:2px">Assigned by ${esc(a.assignedBy)} · ${fmtDate(a.createdAt)}</div>
      </div>
      <span class="assign-badge-pending">Pending</span>
      ${a.scopeType==='missing'?`<button onclick="openFillData(${jsArg(a.id)})" style="padding:7px 14px;border-radius:8px;border:none;background:#6366F1;color:#fff;font-size:12px;cursor:pointer;font-weight:600;white-space:nowrap">กรอกข้อมูล</button>`:''}
    </div>`;
  }).join('');
}
function renderMyAssignments(){
  const me=AUTH.user?.username||'';
  const mine=assignments.filter(a=>a.assignedTo===me&&a.status==='pending');
  const sec=$('#myAssignmentsSection'),list=$('#myAssignmentsList'),pill=$('#assignPill'),btn=$('#assignWorkBtn');
  if(sec&&list){
    if(mine.length===0&&!canAssign()){sec.style.display='none';}
    else{sec.style.display='block';list.innerHTML=_buildAssignCards(mine);if(pill)pill.textContent=mine.length;if(btn)btn.style.display=canAssign()?'':'none';}
  }
}

function updateAssignBtn(){
  const btn=$('#assignWorkBtn');
  if(btn)btn.style.display=canAssign()?'':'none';
  const tBtn=$('#setProjectTargetBtn');
  if(tBtn)tBtn.style.display=canAssign()?'':'none';
}

function renderAwChips(containerId,arr){
  const box=document.getElementById(containerId);if(!box)return;
  box.innerHTML=arr.map((v,i)=>`<span class="chip">${esc(v)}<span class="chip-x" data-i="${i}">×</span></span>`).join('');
  box.querySelectorAll('.chip-x').forEach(x=>{
    x.onclick=()=>{arr.splice(parseInt(x.dataset.i,10),1);renderAwChips(containerId,arr);};
  });
}
function initAwMultiCombo(inputId,chipsId,arr,getOptionsFn){
  upgradeToCombo(inputId,()=>getOptionsFn().filter(v=>!arr.includes(v)));
  const inp=document.getElementById(inputId);
  if(!inp||inp.dataset.multiComboInited)return;
  inp.dataset.multiComboInited='1';
  inp.addEventListener('change',()=>{
    const v=inp.value.trim();
    if(v&&!arr.includes(v)){arr.push(v);renderAwChips(chipsId,arr);}
    _awClearComboVal(inputId);
  });
}

function _awClearComboVal(id){
  const inp=document.getElementById(id);if(!inp)return;
  inp.value='';const wrap=inp.closest('.combo');if(wrap)wrap.classList.remove('has-val');
  inp.dispatchEvent(new Event('change',{bubbles:true}));
}
function showAssignModal(){
  const modal=$('#assignModal');if(!modal)return;
  modal.style.display='flex';
  const role=AUTH.user?.role||'';
  const userProjs=(AUTH.user?.project||'').split(',').map(p=>p.trim()).filter(Boolean);

  awSelProjs.length=0;awSelLocs.length=0;awSelSubs.length=0;awSelEquips.length=0;
  renderAwChips('awProjectChips',awSelProjs);
  renderAwChips('awLocChips',awSelLocs);
  renderAwChips('awSubChips',awSelSubs);
  renderAwChips('awEquipChips',awSelEquips);

  initAwMultiCombo('awProject','awProjectChips',awSelProjs,()=>{
    let projs=uniq(master.map(m=>m.project)).filter(Boolean).sort((a,b)=>a.localeCompare(b,'th'));
    if(role==='leader'&&userProjs.length)projs=projs.filter(p=>userProjs.includes(p));
    return projs;
  });
  upgradeToCombo('awAssignee',()=>{
    const r=AUTH.user?.role||'';
    const ups=(AUTH.user?.project||'').split(',').map(p=>p.trim()).filter(Boolean);
    const targetRoles=r==='admin'||r==='manager'?['leader','inspector']:['inspector'];
    let users=usersCache.filter(u=>targetRoles.includes(u.role)&&u.active!=='false'&&u.active!==false);
    if(r==='leader'&&ups.length)users=users.filter(u=>(u.project||'').split(',').map(p=>p.trim()).some(p=>ups.includes(p)));
    if(awSelProjs.length)users=users.filter(u=>awSelProjs.every(p=>(u.project||'').split(',').map(x=>x.trim()).includes(p)));
    return users.map(u=>(u.name||u.username)+' ('+u.role+')');
  });
  initAwMultiCombo('awLoc','awLocChips',awSelLocs,()=>{
    return uniq(master.filter(m=>!awSelProjs.length||awSelProjs.includes(m.project)).map(m=>m.locName)).filter(Boolean).sort((a,b)=>a.localeCompare(b,'th'));
  });
  initAwMultiCombo('awSub','awSubChips',awSelSubs,()=>{
    return uniq(master.filter(m=>(!awSelProjs.length||awSelProjs.includes(m.project))&&(!awSelLocs.length||awSelLocs.includes(m.locName))).map(m=>m.subName)).filter(Boolean).sort((a,b)=>a.localeCompare(b,'th'));
  });
  initAwMultiCombo('awEquip','awEquipChips',awSelEquips,()=>{
    return uniq(master.filter(m=>(!awSelProjs.length||awSelProjs.includes(m.project))&&(!awSelLocs.length||awSelLocs.includes(m.locName))&&(!awSelSubs.length||awSelSubs.includes(m.subName))).map(m=>m.equipment)).filter(Boolean).sort((a,b)=>a.localeCompare(b,'th'));
  });

  _awClearComboVal('awAssignee');

  document.querySelector('input[name="awScope"][value="project"]').checked=true;
  awScopeChange();
  $('#awNote').value='';
  const td=$('#awTargetDate');if(td)td.value='';
  const hint=$('#awTargetHint');if(hint)hint.innerHTML='';
}

function refreshAssigneeList(){}

function showProjectTargetModal(presetProject){
  const modal=$('#projectTargetModal');if(!modal)return;
  modal.style.display='flex';
  upgradeToCombo('ptProject',()=>{
    const role=AUTH.user?.role||'';
    const ups=(AUTH.user?.project||'').split(',').map(p=>p.trim()).filter(Boolean);
    let projs=uniq(master.map(m=>m.project)).filter(Boolean).sort((a,b)=>a.localeCompare(b,'th'));
    if(role==='leader'&&ups.length)projs=projs.filter(p=>ups.includes(p));
    return projs;
  });
  if(presetProject){
    const inp=$('#ptProject');if(inp)inp.value=presetProject;
    inp?.dispatchEvent(new Event('change',{bubbles:true}));
  } else {
    const inp=$('#ptProject');if(inp)inp.value='';
  }
  $('#ptDeadline').value='';
  $('#ptNote').value='';
  const info=$('#ptCurrentInfo');if(info)info.style.display='none';

  if(presetProject)_ptUpdateCurrentInfo(presetProject);
}
function _ptUpdateCurrentInfo(proj){
  const info=$('#ptCurrentInfo');if(!info)return;
  const dl=getProjectDeadline(proj);
  if(dl){
    const dInp=$('#ptDeadline');if(dInp)dInp.value=dl;
    const existing=targetsCache.find(t=>t.project===proj&&t.username==='__project__');
    if(existing&&existing.note&&$('#ptNote'))$('#ptNote').value=existing.note;
    info.style.display='';
    info.innerHTML=`<div style="font-size:11px;color:var(--ink-soft);margin-top:6px">Current deadline: <b>${dl}</b></div>`;
  } else {
    info.style.display='none';
  }
}
async function saveProjectTarget(){
  const proj=$('#ptProject').value.trim();
  const deadline=$('#ptDeadline').value;
  const note=$('#ptNote').value.trim();
  if(!proj){toast('Please select a project',false);return;}
  if(!deadline){toast('Please select a date',false);return;}
  const r=await api(ACT.saveTarget,{project:proj,username:'__project__',deadline,note});
  if(r&&r.ok){
    toast('Project target saved',true);
    await loadTargets();
    await loadAssignStats();
    $('#projectTargetModal').style.display='none';
  } else {
    toast((r&&r.message)||'An error occurred',false);
  }
}

function awScopeChange(){
  const scope=document.querySelector('input[name="awScope"]:checked')?.value||'project';
  $('#awLocRow').style.display=(scope==='loc'||scope==='sub'||scope==='equip')?'block':'none';
  $('#awSubRow').style.display=(scope==='sub'||scope==='equip')?'block':'none';
  $('#awEquipRow').style.display=(scope==='equip')?'block':'none';
  $('#awMissingRow').style.display=(scope==='missing')?'block':'none';
  if(scope==='missing')renderMissingTable();
  if(scope==='loc'||scope==='sub'||scope==='equip'){_awClearComboVal('awLoc');_awClearComboVal('awSub');_awClearComboVal('awEquip');}
}

function refreshAwCascade(){}

function renderMissingTable(){
  const rows=master.filter(m=>(!awSelProjs.length||awSelProjs.includes(m.project))&&(!m.brand||!m.model||!m.serial));
  const body=$('#awMissingBody');
  const count=$('#awMissingCount');
  if(count)count.textContent='('+rows.length+' records)';
  body.innerHTML=rows.map(m=>{
    const missing=[!m.brand&&'Brand',!m.model&&'Model',!m.serial&&'Serial'].filter(Boolean).join(', ');
    return `<tr>
      <td style="padding:6px 10px"><input type="checkbox" class="aw-missing-chk" data-id="${m.id}"></td>
      <td style="padding:6px 8px;font-size:12.5px">${esc(m.subName)}</td>
      <td style="padding:6px 8px;font-size:12.5px">${esc(m.equipment)}</td>
      <td style="padding:6px 8px;font-size:12px;color:#EF4444">${esc(missing)}</td>
    </tr>`;
  }).join('');
  const sa=$('#awMissingSelectAll');
  if(sa)sa.onchange=e=>body.querySelectorAll('.aw-missing-chk').forEach(c=>c.checked=e.target.checked);
}

async function saveAssignment(){
  if(!awSelProjs.length){toast('Please select at least one project',false);return;}
  const assignee=$('#awAssignee').value;
  if(!assignee){toast('Please select an assignee',false);return;}
  const validUser=usersCache.find(u=>u.username===assignee||((u.name||u.username)+' ('+u.role+')')===assignee);
  const resolvedAssignee=validUser?validUser.username:assignee;
  if(validUser&&['leader','inspector'].includes(validUser.role)){
    const userProjList=(validUser.project||'').split(',').map(p=>p.trim()).filter(Boolean);
    const invalid=awSelProjs.filter(p=>!userProjList.includes(p));
    if(invalid.length){toast('Assignee is not on the project: '+invalid.join(', ')+' — please fix this on the User Management page',false);return;}
  }
  const scope=document.querySelector('input[name="awScope"]:checked')?.value||'project';
  const note=$('#awNote').value.trim();
  const targetDate=$('#awTargetDate')?.value||'';
  for(const proj of awSelProjs){const projDL=getProjectDeadline(proj);if(targetDate&&projDL&&targetDate>projDL){toast('Due date must not be later than the project deadline '+proj+' ('+projDL+')',false);return;}}
  const by=AUTH.user?.username||'';
  let newItems=[];
  if(scope==='missing'){
    const chks=[...document.querySelectorAll('.aw-missing-chk:checked')];
    if(!chks.length){toast('Please select the items you want to fill in',false);return;}
    chks.forEach(c=>{
      const m=master.find(x=>x.id===c.dataset.id);if(!m)return;
      const mf=[!m.brand&&'brand',!m.model&&'model',!m.serial&&'serial'].filter(Boolean);
      newItems.push({id:uid(),project:m.project,scopeType:'missing',locName:m.locName,subName:m.subName,equipment:m.equipment,masterId:m.id,missingFields:mf,assignedTo:resolvedAssignee,assignedBy:by,note,status:'pending',createdAt:Date.now(),doneAt:null,doneData:{},targetDate});
    });
  } else if(scope==='project'){
    awSelProjs.forEach(proj=>newItems.push({id:uid(),project:proj,scopeType:'project',locName:'',subName:'',equipment:'',masterId:'',missingFields:[],assignedTo:resolvedAssignee,assignedBy:by,note,status:'pending',createdAt:Date.now(),doneAt:null,doneData:{},targetDate}));
  } else if(scope==='loc'){
    if(!awSelLocs.length){toast('Please select at least one location',false);return;}
    awSelProjs.forEach(proj=>awSelLocs.forEach(loc=>newItems.push({id:uid(),project:proj,scopeType:'loc',locName:loc,subName:'',equipment:'',masterId:'',missingFields:[],assignedTo:resolvedAssignee,assignedBy:by,note,status:'pending',createdAt:Date.now(),doneAt:null,doneData:{},targetDate})));
  } else if(scope==='sub'){
    if(!awSelSubs.length){toast('Please select at least one sub-location',false);return;}
    const locs=awSelLocs.length?awSelLocs:[''];
    awSelProjs.forEach(proj=>locs.forEach(loc=>awSelSubs.forEach(sub=>newItems.push({id:uid(),project:proj,scopeType:'sub',locName:loc,subName:sub,equipment:'',masterId:'',missingFields:[],assignedTo:resolvedAssignee,assignedBy:by,note,status:'pending',createdAt:Date.now(),doneAt:null,doneData:{},targetDate}))));
  } else if(scope==='equip'){
    if(!awSelEquips.length){toast('Please select at least one equipment',false);return;}
    const locs=awSelLocs.length?awSelLocs:[''];const subs=awSelSubs.length?awSelSubs:[''];
    awSelProjs.forEach(proj=>locs.forEach(loc=>subs.forEach(sub=>awSelEquips.forEach(eq=>newItems.push({id:uid(),project:proj,scopeType:'equip',locName:loc,subName:sub,equipment:eq,masterId:'',missingFields:[],assignedTo:resolvedAssignee,assignedBy:by,note,status:'pending',createdAt:Date.now(),doneAt:null,doneData:{},targetDate})))));
  }
  if(!newItems.length){toast('No records to save',false);return;}
  assignments.push(...newItems);
  await sSet(ASSIGN_KEY,JSON.stringify(assignments));
  if(AUTH.token){for(const a of newItems)await api(ACT.saveAssignment,{assignment:a});}
  $('#assignModal').style.display='none';
  renderMyAssignments();
  await loadAssignStats();
  toast('Assigned Work '+newItems.length+' records',true);
}

let _fillingAssignId=null;
function openFillData(assignId){
  const a=assignments.find(x=>x.id===assignId);if(!a)return;
  const m=master.find(x=>x.id===a.masterId);
  _fillingAssignId=assignId;
  const info=$('#fillDataInfo');
  const fields=$('#fillDataFields');
  if(info)info.innerHTML=`<b>${esc(a.equipment)}</b><br><span style="color:var(--ink-faint)">${esc(a.subName)} · ${esc(a.locName)} · ${esc(a.project)}</span>`;
  if(fields){
    fields.innerHTML=(a.missingFields||[]).map(f=>{
      const label={brand:'Brand',model:'Model',serial:'Serial Number'}[f]||f;
      const cur=m?m[f]||'':'';
      return `<div><label style="font-size:12px;font-weight:600;color:var(--ink-soft);display:block;margin-bottom:4px">${esc(label)}</label><input type="text" class="tin" data-field="${f}" value="${esc(cur)}" placeholder="${esc(label)}…" style="width:100%"></div>`;
    }).join('');
  }
  const modal=$('#fillDataModal');if(modal)modal.style.display='flex';
}

async function saveFillData(){
  if(!_fillingAssignId)return;
  const a=assignments.find(x=>x.id===_fillingAssignId);if(!a)return;
  const doneData={};
  $('#fillDataFields').querySelectorAll('input[data-field]').forEach(inp=>{doneData[inp.dataset.field]=inp.value.trim();});
  a.status='done';a.doneAt=Date.now();a.doneData=doneData;

  const m=master.find(x=>x.id===a.masterId);
  if(m){Object.assign(m,doneData);await persistMaster();if(AUTH.user&&AUTH.user.role==='admin')await masterServer('masterUpsert',{rows:[masterToBackend(m)]});}
  await sSet(ASSIGN_KEY,JSON.stringify(assignments));
  if(AUTH.token)await api(ACT.completeAssignment,{id:a.id,doneData});
  $('#fillDataModal').style.display='none';
  renderMyAssignments();
  toast('Data saved',true);
}

async function exportAssignData(){
  const done=assignments.filter(a=>a.scopeType==='missing'&&a.status==='done');
  if(!done.length){toast('No completed work yet',false);return;}
  const header=['Order','Project','System','Location Type','Location','Sub-location','Equipment Type','Equipment','Brand','Model','Serial Number'];
  const rows=done.map(a=>{
    const m=master.find(x=>x.id===a.masterId)||{};
    return [m.order||'',a.project,m.system||'',m.typeLocation||'',a.locName,a.subName,m.asset||'',a.equipment,a.doneData.brand||m.brand||'',a.doneData.model||m.model||'',a.doneData.serial||m.serial||''];
  });
  try{await loadLib('xlsx');}catch(e){toast('Could not load the Excel library. Check your connection and try again',false); return;}
  const ws=XLSX.utils.aoa_to_sheet([header,...rows]);
  const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'AssignData');
  XLSX.writeFile(wb,'assign_data_'+fileStamp(Date.now())+'.xlsx');
  toast('Download '+done.length+' records',true);
}

